"""Helpers for source-local event display times.

Canonical event times remain true instants in ``start_time`` / ``end_time``.
These helpers only project those instants into a source timezone when an
importer has preserved a trustworthy IANA TZID.
"""

from __future__ import annotations

import re
from datetime import date, datetime
from typing import TYPE_CHECKING, Any
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from django.utils import timezone
from django.utils.formats import date_format

if TYPE_CHECKING:
    from events.models import Event


_OFFSET_ONLY_RE = re.compile(r"^[+-]\d{2}:?\d{2}$")


def clean_display_tzid(value: Any) -> str:
    """Return a valid IANA timezone id or ``""`` when the value is unsafe."""

    if not isinstance(value, str):
        return ""
    tzid = value.strip()
    if not tzid or len(tzid) > 64 or _OFFSET_ONLY_RE.match(tzid):
        return ""
    try:
        ZoneInfo(tzid)
    except (ZoneInfoNotFoundError, ValueError):
        return ""
    return tzid


def display_datetime_for(value: datetime | None, tzid: str | None) -> datetime | None:
    clean_tzid = clean_display_tzid(tzid)
    if value is None or not clean_tzid or timezone.is_naive(value):
        return None
    return value.astimezone(ZoneInfo(clean_tzid))


def display_iso_for(value: datetime | None, tzid: str | None) -> str | None:
    display_value = display_datetime_for(value, tzid)
    if display_value is None:
        return None
    return display_value.isoformat()


def build_display_timezone_fields(
    *,
    start_time: datetime | None,
    end_time: datetime | None,
    start_tzid: str | None,
    end_tzid: str | None = None,
) -> dict[str, Any]:
    """Build ``Event`` display timezone fields from source TZIDs.

    ``end_tzid`` falls back to ``start_tzid`` when omitted, which matches ICS
    events where only ``DTSTART`` carries the zone but the source-local display
    contract still expects both endpoints to stay in the source zone.
    """

    clean_start = clean_display_tzid(start_tzid)
    clean_end = clean_display_tzid(end_tzid) or clean_start
    if not clean_start and clean_end:
        clean_start = clean_end

    start_display = display_datetime_for(start_time, clean_start)
    end_display = display_datetime_for(end_time, clean_end)

    if start_display is None:
        clean_start = ""
    if end_display is None:
        clean_end = ""

    return {
        "start_display_tzid": clean_start,
        "end_display_tzid": clean_end,
        "start_display_date": start_display.date() if start_display else None,
        "end_display_date": end_display.date() if end_display else None,
    }


def assign_display_timezone_fields(
    event: Event, *, start_tzid: str | None, end_tzid: str | None = None
) -> Event:
    fields = build_display_timezone_fields(
        start_time=event.start_time,
        end_time=event.end_time,
        start_tzid=start_tzid,
        end_tzid=end_tzid,
    )
    for field_name, value in fields.items():
        setattr(event, field_name, value)
    return event


def get_event_display_start(event: Event) -> datetime | None:
    return display_datetime_for(event.start_time, event.start_display_tzid)


def get_event_display_end(event: Event) -> datetime | None:
    return display_datetime_for(event.end_time, event.end_display_tzid)


def get_event_display_start_iso(event: Event) -> str | None:
    return display_iso_for(event.start_time, event.start_display_tzid)


def get_event_display_end_iso(event: Event) -> str | None:
    return display_iso_for(event.end_time, event.end_display_tzid)


def _fallback_local(value: datetime) -> datetime:
    if timezone.is_naive(value):
        return value
    return timezone.localtime(value)


def _date_label(value: datetime | date) -> str:
    return str(date_format(value, "l, F j, Y"))


def _time_label(value: datetime) -> str:
    return str(date_format(value, "g:i A"))


def format_event_display_time_label(event: Event) -> str:
    start = get_event_display_start(event) or _fallback_local(event.start_time)
    end = get_event_display_end(event) or _fallback_local(event.end_time)

    if event.is_all_day:
        return f"{_date_label(start)} - All Day"

    if start.date() == end.date():
        return f"{_date_label(start)} from {_time_label(start)} to {_time_label(end)}"

    return (
        f"{_date_label(start)} {_time_label(start)} to "
        f"{_date_label(end)} {_time_label(end)}"
    )

