import operator
import re
from collections.abc import Iterable
from typing import Any, cast

import nh3
from django import template
from django.db.models import QuerySet, Sum
from django.utils.html import escape, linebreaks
from django.utils.safestring import SafeString, mark_safe

from events.display_time import format_event_display_time_label

register = template.Library()

SPORT_ICON_MAP: dict[str, str] = {
    "SOCCER": "mdi mdi-soccer",
    "BASKETBALL": "mdi mdi-basketball",
    "BASEBALL": "mdi mdi-baseball",
    "HOCKEY": "mdi mdi-hockey-puck",
    "ROWING": "mdi mdi-rowing",
    "BALLET": "mdi mdi-human-female-dance",
}
DEFAULT_SPORT_ICON = "mdi mdi-trophy"
EVENT_DESCRIPTION_ALLOWED_TAGS = {
    "a",
    "br",
    "em",
    "li",
    "ol",
    "p",
    "strong",
    "ul",
}
EVENT_DESCRIPTION_ALLOWED_ATTRIBUTES = {"a": {"href", "title"}}
EVENT_DESCRIPTION_ALLOWED_URL_SCHEMES = {"http", "https", "mailto"}
HTML_TAG_RE = re.compile(r"</?[a-zA-Z][^>]*>")


@register.simple_tag
def sport_icon_class(subcategory: str | None) -> str:
    """Return the MDI CSS class for a sports subcategory."""
    if not subcategory:
        return DEFAULT_SPORT_ICON
    return SPORT_ICON_MAP.get(subcategory, DEFAULT_SPORT_ICON)


@register.filter
def event_description_html(description: str | None) -> str:
    if not description:
        return ""

    if not HTML_TAG_RE.search(description):
        return str(linebreaks(description))

    clean_html = nh3.clean(
        description,
        tags=EVENT_DESCRIPTION_ALLOWED_TAGS,
        attributes=EVENT_DESCRIPTION_ALLOWED_ATTRIBUTES,
        url_schemes=EVENT_DESCRIPTION_ALLOWED_URL_SCHEMES,
    )
    # nh3 has parsed and sanitized the imported calendar HTML before Django
    # treats this description as renderable markup.
    # nosemgrep: python.django.security.audit.avoid-mark-safe.avoid-mark-safe
    return mark_safe(clean_html)  # noqa: S308  # nosec


@register.filter
def event_display_time_label(event: Any) -> str:
    return format_event_display_time_label(event)


@register.filter
def get_item(dictionary: Any, key: Any) -> Any:
    """
    Gets an item from a dictionary using the key.
    Usage: {{ my_dict|get_item:key_variable }}
    """
    if dictionary is None:
        return None
    return dictionary.get(str(key))


@register.filter
def mul(value: Any, arg: Any) -> float:
    """
    Multiplies the value by the argument.
    Usage: {{ value|mul:100 }}
    """
