    """
    Maps a sequence of objects to a sequence of attributes.
    Usage: {{ my_list|map:'attribute_name' }}
    """
    return [getattr(item, attr) for item in sequence]


@register.filter
def sum(sequence: Any, attr: str | None = None) -> float | int:
    """
    Sums the attribute values of a sequence of objects.
    Usage: {{ my_list|sum:'attribute_name' }}
    If no attribute is provided, sums the items directly.
    """
    if attr:
        try:
            # For QuerySets, use Django's Sum aggregation
            if hasattr(sequence, "aggregate"):
                return sequence.aggregate(Sum(attr))[f"{attr}__sum"] or 0
            # For regular sequences
            return sum(getattr(item, attr, 0) for item in sequence)
        except (TypeError, AttributeError):
            return 0
    else:
        try:
            return sum(sequence)
        except (TypeError, ValueError):
            return 0


@register.filter
def selectattr(sequence: Iterable[Any], args: str) -> list[Any]:
    """
    Filters a sequence of objects by comparing an attribute to a value.
    Usage: {{ my_list|selectattr:"attribute,eq,value" }}
    Supports operators: eq (equals), ne (not equals), gt (greater than), lt (less than)
    """
    if not sequence:
        return []

    try:
        # Parse arguments
        parts = args.split(",", 2)
        if len(parts) != 3:
            return []

        attr, op_name, value = parts

        # Define operators
        ops = {
            "eq": operator.eq,
            "ne": operator.ne,
            "gt": operator.gt,
            "lt": operator.lt,
            "ge": operator.ge,
            "le": operator.le,
        }

        if op_name not in ops:
            return []

        op_func = ops[op_name]

        # Filter the sequence
        return [item for item in sequence if op_func(getattr(item, attr, None), value)]  # type: ignore[arg-type]
    except (AttributeError, ValueError, TypeError):
        return []


