def _event_uid(event: Event) -> str:
    external_id = event.external_id or ""
    if ":" in external_id:
        return external_id.split(":", 1)[1]
    return external_id


def _proposal_tzids(proposal: dict[str, Any]) -> tuple[str, str]:
    start_tzid = (
        proposal.get("start_tzid")
        or proposal.get("timezone")
        or proposal.get("tz")
        or ""
    )
    end_tzid = proposal.get("end_tzid") or proposal.get("timezone") or ""
    return str(start_tzid or ""), str(end_tzid or "")


def _proposal_matches_event(proposal: dict[str, Any], event: Event) -> bool:
    uid = str(proposal.get("uid") or "")
    return bool(uid and uid == _event_uid(event))


def _capture_proposal(capture: InboxCapture, event: Event) -> dict[str, Any] | None:
    payload = capture.normalized_payload or {}
    proposals = [
        proposal
        for proposal in payload.get("proposals", [])
        if isinstance(proposal, dict)
    ]
    if not proposals:
        return None
    for proposal in proposals:
        if _proposal_matches_event(proposal, event):
            return proposal
    if len(proposals) == 1:
        return proposals[0]
    return None


