class Command(BaseCommand):
    help = (
        "Backfill Event source-local display timezone fields. Dry-run is the "
        "default; pass --apply to write changes. Writes use queryset update() "
        "so display-only repairs do not re-queue calendar sync or geocoding."
    )

    def add_arguments(self, parser: CommandParser) -> None:
        parser.add_argument(
            "--apply",
            action="store_true",
            help="Persist display timezone fields. Without this, only report changes.",
        )
        parser.add_argument(
            "--event-id",
            action="append",
            default=[],
            help="Restrict to an event id. May be supplied multiple times.",
        )
        parser.add_argument(
            "--family-id",
            default="",
            help="Restrict automatic recovery to one family id.",
        )
        parser.add_argument(
            "--start-tzid",
            default="",
            help="Explicit IANA TZID for one-off --event-id repair.",
        )
        parser.add_argument(
            "--end-tzid",
            default="",
            help="Explicit IANA TZID for one-off --event-id repair; defaults to --start-tzid.",
        )
        parser.add_argument(
            "--limit",
            type=int,
            default=None,
            help="Maximum inbox captures/intakes to scan per recovery source.",
        )

    def handle(self, *args: Any, **options: Any) -> None:
        apply: bool = options["apply"]
        event_ids = {str(event_id) for event_id in options["event_id"]}
        scoped_event_ids = event_ids or None
        family_id: str = options["family_id"]
        start_tzid: str = options["start_tzid"]
        end_tzid: str = options["end_tzid"] or start_tzid
        limit: int | None = options["limit"]

        if (start_tzid or end_tzid) and not event_ids:
            self.stderr.write("--start-tzid/--end-tzid require at least one --event-id")
            return

        candidates: list[DisplayTimezoneCandidate] = []
        if event_ids and start_tzid:
            candidates.extend(
                _manual_candidates(
                    event_ids=event_ids,
                    start_tzid=start_tzid,
                    end_tzid=end_tzid,
                )
            )
        candidates.extend(
            _capture_candidates(
                event_ids=scoped_event_ids,
                family_id=family_id or None,
                limit=limit,
            )
        )
        candidates.extend(
            _itinerary_candidates(
                event_ids=scoped_event_ids,
                family_id=family_id or None,
                limit=limit,
            )
        )

        seen_events: set[str] = set()
        scanned = 0
        invalid = 0
        updated = 0
        unchanged = 0

        for candidate in candidates:
            scanned += 1
            event_key = str(candidate.event.pk)
            if event_key in seen_events and candidate.source != "manual":
                continue
            seen_events.add(event_key)

            changes = _changed_display_fields(candidate.event, candidate)
            if not changes:
                invalid += 1
                continue

            if apply:
                Event.objects.filter(pk=candidate.event.pk).update(**changes)
                updated += 1
            else:
                unchanged += 1

            self.stdout.write(
                ("UPDATE" if apply else "DRY-RUN")
                + f" event={candidate.event.pk} source={candidate.source} "
                + " ".join(f"{key}={value}" for key, value in changes.items())
            )

        verb = "Updated" if apply else "Would update"
        self.stdout.write(
            self.style.SUCCESS(
                f"{verb} {updated if apply else unchanged} events; "
                f"scanned {scanned} candidates, skipped {invalid} invalid/unchanged."
            )
